-- M708-01 einleitungsart
update public.fields set verification_status='verified_against_standard', verification_quote='Indirekteinleitung meint eine indirekte Gewässerbenutzung über die vorherige Ableitung des Abwassers und Behandlung in einer anderen Abwasseranlage, die in der Regel eine kommunale Kläranlage ist. | Für die direkte Abwassereinleitung in ein Gewässer ist eine wasserbehördliche Erlaubnis (§§ 8, 9 Absatz 1 Nr. 4, § 10 WHG) erforderlich. | Bei der direkten Übernahme von Abwasser aus der Milchverarbeitung durch eine kommunale Kläranlage über eine eigene Leitung ist grundsätzlich keine nennenswerte Vorbehandlung außer einer Neutralisation erforderlich, falls die Kapazität der kommunalen Kläranlage ausreicht. — printed p.21', verification_note='md-verified 2026-09-07 (3.4 / 3.5 / 8.5, printed p.21–23 and 66) [VC] — clause_reference reads "WHG; Anhang 3 AbwV"; the three discharge paths are defined in 3.4/3.5/8.5 — retag staged', verified_at=now() where id='2d598014-852d-4a4b-8f9f-670ad26972f2' and verification_status not in ('verified_against_standard','corrected');

