-- M708-02 wasserwiederverwendung_geplant
update public.fields set verification_status='verified_against_standard', verification_quote='Nach Inkrafttreten der EU-Verordnung über Mindestanforderungen an die Wiederverwendung (Verordnung (EU) 2020/741) von Abwasser zum Zweck der landwirtschaftlichen Bewässerung erfolgt derzeit deren nationale Umsetzung. Es sind sowohl Zulassungspflichten für die Aufbereitungsanlagen als auch für die Verwendung von aufbereitetem Abwasser als Wasser zu erwarten mit dem Ziel, Gesund-heits- und Umweltrisiken auszuschließen, insbesondere um das Grundwasser und seine Nutzungen zu schützen. — printed p.23', verification_note='md-verified 2026-09-07 (3.6, printed p.23) [VC]', verified_at=now() where id='d3b65049-30d4-47da-b19b-47c504520d99' and verification_status not in ('verified_against_standard','corrected');

