-- M708-19 aufenthaltszeit_anaerob
update public.fields set verification_status='verified_against_standard', verification_quote='Der Anaerobreaktor wird in aller Regel im mesophilen Temperaturbereich, d. h. bei etwa $38^{\circ} \mathrm{C}$, betrieben. Um eine hohe Biogasausbeute und einen weitgehenden Abbau der abbaubaren organischen Substanz zu erzielen, sollte dabei eine hohe Aufenthaltszeit von 20 bis 30 Tagen gewählt werden. Dabei liegt die CSB-Raumbelastung zwischen $5 \mathrm{~kg} /\left(\mathrm{m}^{3} \cdot \mathrm{~d}\right)$ CSB und $20 \mathrm{~kg} /\left(\mathrm{m}^{3} \cdot \mathrm{~d}\right)$ CSB. — printed p.68', verification_note='md-verified 2026-09-07 (8.6.2, printed p.68) [VC]', verified_at=now() where id='1a24d033-f215-4d39-9757-f5a1dbc652c4' and verification_status not in ('verified_against_standard','corrected');

