-- M708-19 biogas_ertrag
update public.fields set verification_status='verified_against_standard', verification_quote='Ziel der anaeroben Schlammbehandlung ist die Nutzung der in den Flotaten, Überschussschlämmen und Co-Substraten enthaltenen chemisch gebundenen Energie in Form von Methan, welches im entstandenen „Biogas“ enthalten ist. Das Biogas kann entweder direkt im Produktionsbetrieb genutzt werden oder es wird aufbereitet und als „Biomethan“ in das Gasnetz eingespeist. | Die Biogaserträge werden (bezogen auf den Normzustand) in l/kg oTR angegeben, um die verschiedenen Einsatzstoffe bezüglich der theoretischen Gasausbeute vergleichen zu können. | Tabelle 18: Gasertrag von verschiedenen Produkten bzw. Stoffen aus der milchverarbeitenden Industrie — printed p.68', verification_note='md-verified 2026-09-07 (8.6.2 / 7.3.2.3 / Tabelle 18, printed p.68 and 54) [VC] — the guideline expresses gas yield in l/kg oTR resp. m³/t FM (Tabelle 18); the encoded unit Nm³/d is a plant-level derivation — unit note staged', verified_at=now() where id='2b2fe9de-080b-405c-b52b-98991b76f622' and verification_status not in ('verified_against_standard','corrected');

