-- M708-20 map_massenertrag
update public.fields set verification_status='verified_against_standard', verification_quote='Die Rückgewinnung erfolgt in der Regel durch eine gezielte Fällung von Magnesiumammoniumphosphat (MAP). Die MAP-Fällung ist ein chemischer Prozess, bei dem Magnesium, Ammonium und Phosphat miteinander reagieren, um ein festes, weißes, kristallines Salz zu bilden. | Hinsichtlich der Elimination von Stickstoff und Phosphor ist zu beachten, dass bei der MAP-Fällung entsprechend dem Verhältnis der Molmassen wesentlich mehr Phosphor, nämlich rund 2,2 -mal so viel, entfernt wird als Ammonium-Stickstoff. — printed p.69', verification_note='md-verified 2026-09-07 (8.7.2, printed p.69–71) [VC] — no MAP mass yield is printed; it follows from the influent PO4-P load and the molar-mass ratio', verified_at=now() where id='b5d80d07-c376-41bc-8e4c-e7e3dfee0f7a' and verification_status not in ('verified_against_standard','corrected');

-- M708-20 v_map_reaktor
