update public.fields set verification_status='verified_against_standard', verification_quote='Das weitgehend feststofffreie, alkalische Abwasser wird am Kopf der Strippkolonne aufgegeben. Über dem Sumpf der Strippkolonne wird wasserdampfgesättigte Luft eingespeist, die im Gegenstrom zur | Flüssigkeit die Kolonne von unten nach oben durchströmt und dabei das in der Flüssigkeit enthaltene Ammoniak austreibt. Die über Kopf abgehenden ammoniakhaltigen Brüden werden in die benachbarte Absorptionskolonne (Scrubber) eingeleitet. — printed p.72', verification_note='md-verified 2026-09-07 (8.7.3, printed p.71–73) [VC] — the guideline describes the counter-current stripping column qualitatively; no dimensioning values are printed', verified_at=now() where id='6493bf52-a402-448a-ac0a-6c021074e1a6' and verification_status not in ('verified_against_standard','corrected');

