-- M708-24 wasserwiederverwendung_volumen
update public.fields set verification_status='verified_against_standard', verification_quote='In der Praxis hat es sich gezeigt, dass insbesondere die Wiederverwendung des Prozesswassers aus einem einzelnen Verarbeitungsschritt oder die Wiedergewinnung von Brüdenkondensaten bzw. von Permeaten anstelle der Aufbereitung vermischter Prozesswasserströme vorteilhaft ist. Bei diesen Anwendungen ist die Zusammensetzung des Wassers bekannt und im Allgemeinen von gleichbleibender Qualität, sodass ein Aufbereitungsprozess sicher ausgelegt und betrieben werden kann. — printed p.74', verification_note='md-verified 2026-09-07 (9.2, printed p.74–75) [VC] — the guideline names the reusable process-water sources; no reuse volume is printed', verified_at=now() where id='9e2eb68f-0147-4b30-bb33-a42ebb76caa3' and verification_status not in ('verified_against_standard','corrected');

