-- equation Gl-1
update public.equations set verification_status='verified_against_standard', verification_quote='Der für die MAP-Fällung genutzte pH -Bereich bedingt, dass der Phosphor hauptsächlich in Form von Hydrogenphosphat vorliegt und so die Fällungsreaktion nach folgender Gleichung (1) erfolgt: | \mathrm{Mg}^{2+}+\mathrm{NH}_{4}^{+}+\mathrm{HPO}_{4}^{2-}+\mathrm{OH}^{-}+5 \mathrm{H}_{2} \mathrm{O} \rightarrow \mathrm{MgNH}_{4} \mathrm{PO}_{4} \cdot 6 \mathrm{H}_{2} \mathrm{O} \tag{1} — printed p.69', verification_note='md-verified 2026-09-07 (8.7.2, Gleichung (1), printed p.69–71) [VC]', verified_at=now() where id='d99f5cbf-2e9d-46a2-902f-66a1f196d031' and verification_status <> 'verified_against_standard';
